export async function listTools() {
  return [
    {
      name: 'customer_lookup',
      description: 'Look up a customer by their customer id.',
      inputSchema: {
        type: 'object',
        properties: {
          customer_id: {
            type: 'string',
            description: 'The unique identifier of the customer to look up.',
          },
        },
        required: ['customer_id'],
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'customer_lookup') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  if (!('customer_id' in args)) {
    throw new Error("Invalid arguments: 'customer_id' is required");
  }

  const id = args.customer_id;
  if (typeof id !== 'string' || id.length === 0) {
    throw new Error("Invalid arguments: 'customer_id' must be a non-empty string");
  }

  const customer = customers[id];
  if (!customer) {
    throw new Error(`Unknown customer: ${id}`);
  }

  return {
    content: [
      {
        type: 'text',
        text: `${customer.name} (tier: ${customer.tier})`,
      },
    ],
  };
}

